mapper.select:
SELECT f.*, CAST(f.last_run_id AS varchar) AS last_run_id
  FROM pmc_vuln_finding f
 WHERE f.server_id = #{serverId}
   AND f.check_code = #{checkCode}
   AND f.source = #{source}

mapper.update:
UPDATE pmc_vuln_finding
   SET status = 'FIXED', upd_user = #{updUser}, upd_dt = now()
 WHERE server_id = #{serverId}
   AND source = #{source}
   AND status IN ('OPEN','RECURRED')

   AND check_code NOT IN
   #{c}

UPDATE pmc_vuln_finding
   SET status = #{status}, upd_user = #{updUser}, upd_dt = now()
 WHERE finding_id = #{findingId}

mapper.select:
SELECT f.finding_id, f.server_id, f.check_code, f.source, f.category, f.title, f.severity, f.status, f.first_detected_at, f.last_detected_at, f.occurrence_count, f.recur_count, CAST(f.last_run_id AS varchar) AS last_run_id, f.reg_dt, f.upd_dt, s.hostname AS hostname, s.service_name AS service_name FROM pmc_vuln_finding f JOIN pmc_server s ON s.server_id = f.server_id
AND f.server_id = #{serverId} AND f.severity = #{severity} AND f.status = #{status}
ORDER BY CASE f.severity WHEN '상' THEN 0 WHEN '중' THEN 1 ELSE 2 END, f.last_detected_at DESC

SELECT * FROM pmc_vuln_action
 WHERE finding_id = #{findingId}
 ORDER BY action_dt DESC, action_id DESC
